#include "compositors/niri/niri_config_overview.h"

#include "compositors/niri/niri_config_files.h"

#include <cctype>
#include <filesystem>
#include <system_error>

namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Noctalia from Control Center → Niri. Edits here are overwritten.\n";

    constexpr std::string_view kBackdropKdl = R"(layer-rule {
    match namespace="^noctalia-backdrop"
    place-within-backdrop true
}
)";

    constexpr std::string_view kStationaryKdl = R"(layer-rule {
    match namespace="^noctalia-wallpaper"
    place-within-backdrop true
}

layout {
    background-color "transparent"
}

overview {
    workspace-shadow {
        off
    }
}
)";

    [[nodiscard]] bool isHexColor(std::string_view hex) {
      if (hex.size() != 7 || hex.front() != '#') {
        return false;
      }
      for (std::size_t i = 1; i < hex.size(); ++i) {
        if (std::isxdigit(static_cast<unsigned char>(hex[i])) == 0) {
          return false;
        }
      }
      return true;
    }

  } // namespace

  std::filesystem::path overviewIncludePath() { return includePath(kOverviewIncludeFileName); }

  std::string sanitizedFlatColorHex(std::string_view hex) {
    if (isHexColor(hex)) {
      return std::string(hex);
    }
    return std::string(kDefaultFlatOverviewColor);
  }

  bool overviewWantsBackdrop(NiriOverviewPreset preset) { return preset == NiriOverviewPreset::Backdrop; }

  std::string kdlForOverview(const OverviewSettings& settings) {
    std::string body(kManagedHeader);
    switch (settings.preset) {
    case NiriOverviewPreset::Backdrop:
      body += kBackdropKdl;
      break;
    case NiriOverviewPreset::Stationary:
      body += kStationaryKdl;
      break;
    case NiriOverviewPreset::Flat:
      body += "overview {\n    backdrop-color \"";
      body += sanitizedFlatColorHex(settings.flatColorHex);
      body += "\"\n}\n";
      break;
    case NiriOverviewPreset::None:
      body += "// Overview wallpaper preset: none.\n";
      break;
    }
    return body;
  }

  InstallResult saveNiriOverview(const OverviewSettings& settings) {
    return saveNiriOverviewInto(configPath(), settings);
  }

  InstallResult saveNiriOverviewInto(const std::filesystem::path& configFile, const OverviewSettings& settings) {
    InstallResult result;
    if (configFile.empty()) {
      result.error = "niri config path is unknown";
      return result;
    }
    std::error_code ec;
    if (!std::filesystem::exists(configFile, ec) || ec) {
      result.error = "niri config not found";
      return result;
    }
    const auto include = configFile.parent_path() / std::string(kOverviewIncludeFileName);
    if (!writeFile(include, kdlForOverview(settings), result.error)) {
      return result;
    }
    if (!appendInclude(configFile, kOverviewIncludeFileName, result.error)) {
      return result;
    }
    result.ok = true;
    result.added = 1;
    return result;
  }

} // namespace compositors::niri
